from itertools import permutations

def calculate_E(a, b, c):
    """Calculates the expression E for a triple (a, b, c)."""
    e1 = a + b + c
    e2 = a*b + b*c + c*a
    e3 = a * b * c

    # E = ((a+b+c)(ab+bc+ca)+a+b+c) / (4abc)
    numerator = e1 * (e2 + 1)
    denominator = 4 * e3

    if denominator == 0:
        return None # Should not happen with positive integers

    return numerator / denominator

# Search space: max(a, b, c) <= 10
limit = 10
results = {}

# Iterate through distinct triples (we enforce order a < b < c to avoid duplicates)
for a in range(1, limit + 1):
    for b in range(a + 1, limit + 1):
        for c in range(b + 1, limit + 1):
            E = calculate_E(a, b, c)

            if E is not None and E == int(E):
                n = int(E)
                if n not in results:
                    results[n] = []
                results[n].append((a, b, c))

print(f"Integer values found for n within max(a,b,c) <= {limit}: {list(results.keys())}")
print("Details:")
for n, triples in results.items():
    print(f"n={n}: {triples}")

